-- Owner decision 2026-11-16: a card execution's recovery reports, launch
-- proof, launch scope and the wait-reason and worker-health details carry no
-- size of ours below the database's own: each is held only to 1 MiB, a bound
-- no report reaches, where they were 4 KiB, 8 KiB, 2 KiB, 8 KiB and 2 KiB. Only
-- the byte bound of each CHECK changes; every other term is as it was.
-- Rollback: drop and add each constraint again with its earlier bound (no row
-- over it exists before this change).
ALTER TABLE "AmuxV22TaskRecoveryEvidence"
  DROP CONSTRAINT "AmuxV22RecoveryEvidence_shape_check",
  ADD CONSTRAINT "AmuxV22RecoveryEvidence_shape_check" CHECK ((("requestKind" = ANY (ARRAY['inspect'::text, 'safe_stop'::text])) AND (("hostInvocationId" IS NULL) OR ("hostInvocationId" ~ '^[a-f0-9]{32}$'::text)) AND ("evidenceDigest" ~ '^[a-f0-9]{64}$'::text) AND (jsonb_typeof(report) = 'object'::text) AND (pg_column_size(report) <= 1048576) AND ((("requestKind" = 'inspect'::text) AND ("sourceEvidenceId" IS NULL) AND ("sourceEvidenceDigest" IS NULL) AND ("stopJournalBindingDigest" IS NULL) AND ("stopJournalEntryDigest" IS NULL) AND ("stopAcknowledgement" IS NULL) AND ("processState" IS NULL) AND ((verified AND (reason IS NULL) AND ("hostInvocationId" IS NOT NULL)) OR ((NOT verified) AND (reason = ANY (ARRAY['terminal_success'::text, 'legacy_invocation_unbound'::text, 'inspection_unverified'::text, 'external_effects_unknown'::text, 'workspace_unverified'::text, 'recovery_identity_changed'::text, 'runtime_observation_unverified'::text]))))) OR (("requestKind" = 'safe_stop'::text) AND ("sourceEvidenceId" IS NOT NULL) AND ("sourceEvidenceDigest" ~ '^[a-f0-9]{64}$'::text) AND ("hostInvocationId" IS NULL) AND ("stopJournalBindingDigest" ~ '^[a-f0-9]{64}$'::text) AND ("stopJournalEntryDigest" ~ '^[a-f0-9]{64}$'::text) AND ("stopAcknowledgement" = ANY (ARRAY['acknowledged'::text, 'outcome_unknown'::text, 'not_issued'::text])) AND ("processState" = ANY (ARRAY['gone'::text, 'present'::text, 'unknown'::text])) AND ((verified AND (reason IS NULL) AND ("processState" = 'gone'::text)) OR ((NOT verified) AND (reason = ANY (ARRAY['safe_stop_identity_changed'::text, 'safe_stop_config_unverified'::text, 'safe_stop_profile_not_unique'::text, 'safe_stop_other_work_present'::text, 'safe_stop_journal_unverified'::text, 'safe_stop_process_present'::text, 'safe_stop_process_unknown'::text, 'safe_stop_kernel_proof_stale'::text]))))))));

ALTER TABLE "AmuxV22ReadOnlyLaunchProof"
  DROP CONSTRAINT "AmuxV22ReadOnlyLaunchProof_shape_check",
  ADD CONSTRAINT "AmuxV22ReadOnlyLaunchProof_shape_check" CHECK ((("proofDigest" ~ '^[a-f0-9]{64}$'::text) AND (observation = ANY (ARRAY['current'::text, 'worker_identity_changed'::text, 'launcher_config_mismatch'::text, 'profile_config_mismatch'::text, 'scope_mismatch'::text])) AND (jsonb_typeof(report) = 'object'::text) AND (pg_column_size(report) <= 1048576) AND ((verified AND (observation = 'current'::text) AND (reason IS NULL)) OR ((NOT verified) AND (reason IS NOT NULL)))));

ALTER TABLE "AmuxV22ReadOnlyLaunchCheck"
  DROP CONSTRAINT "AmuxV22ReadOnlyLaunchCheck_shape_check",
  ADD CONSTRAINT "AmuxV22ReadOnlyLaunchCheck_shape_check" CHECK ((("taskId" = 'c48886b9-86f8-4631-8db8-c0b288a707af'::text) AND ("priorAttemptId" = '97858395-3d66-42fa-9bfb-0e5a6cba39d8'::text) AND ("targetHost" = 'amux-ubuntu'::text) AND ("workerGeneration" >= 1) AND (provider = 'anthropic'::text) AND ("modelId" ~ '^claude-[A-Za-z0-9._-]{1,120}$'::text) AND (("additionalCapMicroUsd" >= 1) AND ("additionalCapMicroUsd" <= 3400000)) AND ("worstExposureMicroUsd" = (3400000 + "additionalCapMicroUsd")) AND ("worstExposureMicroUsd" <= 6800000) AND ("requestDigest" ~ '^[a-f0-9]{64}$'::text) AND ("riskAcceptanceDigest" ~ '^[a-f0-9]{64}$'::text) AND ("sourceEvidenceDigest" ~ '^[a-f0-9]{64}$'::text) AND ("briefDigest" ~ '^[a-f0-9]{64}$'::text) AND ("routePolicyDigest" ~ '^[a-f0-9]{64}$'::text) AND ("costReceiptDigest" ~ '^[a-f0-9]{64}$'::text) AND ("costDigest" ~ '^[a-f0-9]{64}$'::text) AND ("launchScopeDigest" ~ '^[a-f0-9]{64}$'::text) AND (jsonb_typeof("launchScope") = 'object'::text) AND (pg_column_size("launchScope") <= 1048576) AND (("launchScope" ->> 'version'::text) = '1'::text) AND (((NOT ("launchScope" ? 'executorKind'::text)) AND (("launchScope" ->> 'launcherPolicyVersion'::text) = 'amux-v22-read-only-retry-v1'::text) AND (("launchScope" ->> 'role'::text) = 'investigate'::text) AND (("launchScope" -> 'allowedTools'::text) = '["Glob", "Grep", "Read"]'::jsonb)) OR ((("launchScope" - ARRAY['version'::text, 'executorKind'::text, 'launcherConfigDigest'::text, 'apiExecutionFrameDigest'::text]) = '{}'::jsonb) AND ("launchScope" ? 'version'::text) AND ("launchScope" ? 'executorKind'::text) AND ("launchScope" ? 'launcherConfigDigest'::text) AND ("launchScope" ? 'apiExecutionFrameDigest'::text) AND (("launchScope" ->> 'executorKind'::text) = 'read_only_api_retry_v1'::text) AND (("launchScope" ->> 'launcherConfigDigest'::text) ~ '^[a-f0-9]{64}$'::text) AND (("launchScope" ->> 'apiExecutionFrameDigest'::text) ~ '^[a-f0-9]{64}$'::text)))));

ALTER TABLE "AmuxCardWaitReason"
  DROP CONSTRAINT "AmuxCardWaitReason_shape_check",
  ADD CONSTRAINT "AmuxCardWaitReason_shape_check" CHECK ((("lastSeenAt" >= "firstSeenAt") AND ("seenCount" >= 1) AND (stage = ANY (ARRAY['promotion'::text, 'claim'::text])) AND (code ~ '^[a-z0-9_]{1,64}$'::text) AND (jsonb_typeof(detail) = 'object'::text) AND (octet_length((detail)::text) <= 1048576)));

ALTER TABLE "AmuxWorkerHealthSignal"
  DROP CONSTRAINT "AmuxWorkerHealthSignal_shape_check",
  ADD CONSTRAINT "AmuxWorkerHealthSignal_shape_check" CHECK ((("workerName" ~ '^[A-Za-z0-9._:-]{1,120}$'::text) AND (source = ANY (ARRAY['login_keepalive'::text, 'auth_stage'::text, 'sidecar'::text])) AND (signal ~ '^[a-z0-9_]{1,64}$'::text) AND (jsonb_typeof(detail) = 'object'::text) AND (octet_length((detail)::text) <= 1048576) AND ("receivedAt" >= "firstSeenAt")));
